class Solution {
    public:
        string lexGreaterPermutation(string s, string target) {
                int n = s.length();
                        vector<int> s_counts(26, 0);
                                
                                        // Count frequencies of all characters in s
                                                for (char c : s) {
                                                            s_counts[c - 'a']++;
                                                                    }

                                                                            // Try to find the latest possible divergence point 
                                                                                    for (int i = n - 1; i >= 0; --i) {
                                                                                                vector<int> current_counts = s_counts;
                                                                                                            bool can_form_prefix = true;
                                                                                                                        
                                                                                                                                    // 1. Try to form the prefix exactly matching target[0...i-1]
                                                                                                                                                for (int j = 0; j < i; ++j) {
                                                                                                                                                                int c = target[j] - 'a';
                                                                                                                                                                                if (current_counts[c] > 0) {
                                                                                                                                                                                                    current_counts[c]--;
                                                                                                                                                                                                                    } else {
                                                                                                                                                                                                                                        can_form_prefix = false;
                                                                                                                                                                                                                                                            break;
                                                                                                                                                                                                                                                                            }
                                                                                                                                                                                                                                                                                        }

                                                                                                                                                                                                                                                                                                    if (!can_form_prefix) continue;

                                                                                                                                                                                                                                                                                                                // 2. Find the smallest available character strictly greater than target[i]
                                                                                                                                                                                                                                                                                                                            int target_char = target[i] - 'a';
                                                                                                                                                                                                                                                                                                                                        int best_char = -1;
                                                                                                                                                                                                                                                                                                                                                    for (int c = target_char + 1; c < 26; ++c) {
                                                                                                                                                                                                                                                                                                                                                                    if (current_counts[c] > 0) {
                                                                                                                                                                                                                                                                                                                                                                                        best_char = c;
                                                                                                                                                                                                                                                                                                                                                                                                            break;
                                                                                                                                                                                                                                                                                                                                                                                                                            }
                                                                                                                                                                                                                                                                                                                                                                                                                                        }

                                                                                                                                                                                                                                                                                                                                                                                                                                                    // 3. If found, construct and return the result
                                                                                                                                                                                                                                                                                                                                                                                                                                                                if (best_char != -1) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                string res = target.substr(0, i);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                res += (char)(best_char + 'a');
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                current_counts[best_char]--;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                // Append the remaining characters in sorted (ascending) order
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                for (int c = 0; c < 26; ++c) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    res += string(current_counts[c], c + 'a');
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    return res;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                // If no valid permutation is strictly greater, return an empty string
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        return "";
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            };
